@import "@fontsource-variable/geist";
@import "@fontsource-variable/inter";

/* Light: Huly's pale bands. Headings near-black, body a softer graphite. */
:root {
  --background: oklch(0.973 0 0);
  --foreground: oklch(0.16 0.006 260);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.16 0.006 260);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.16 0.006 260);
  --primary: oklch(0.2 0.006 265);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.945 0.002 286);
  --secondary-foreground: oklch(0.22 0.006 265);
  --muted: oklch(0.95 0.002 286);
  --muted-foreground: oklch(0.5 0.01 260);
  --accent: oklch(0.935 0.004 286);
  --accent-foreground: oklch(0.2 0.006 265);
  --destructive: oklch(0.66 0.21 25);
  --destructive-foreground: oklch(0.99 0 0);
  --border: oklch(0.905 0.003 286);
  --input: oklch(0.88 0.004 286);
  --ring: oklch(0.62 0.13 262);
  --highlight: oklch(0.72 0.16 40);
  --highlight-foreground: oklch(0.2 0.05 40);
  --glow: oklch(0.64 0.14 268);
  --chart-1: oklch(0.62 0.22 5);
  --chart-2: oklch(0.62 0.18 148);
  --chart-3: oklch(0.6 0.16 250);
  --chart-4: oklch(0.9 0.12 95);
  --chart-5: oklch(0.58 0.2 305);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.16 0.006 260);
  --sidebar-primary: oklch(0.2 0.006 265);
  --sidebar-primary-foreground: oklch(0.99 0 0);
  --sidebar-accent: oklch(0.935 0.004 286);
  --sidebar-accent-foreground: oklch(0.2 0.006 265);
  --sidebar-border: oklch(0.905 0.003 286);
  --sidebar-ring: oklch(0.62 0.13 262);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Geist Variable", "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 78.5rem;
  --page-gutter: 1.25rem;
  --section-y: 5rem;
}

/* Dark: the hero / CTA black, #111 cards, a light-grey primary pill, blue-violet glow. */
.dark {
  --background: oklch(0.135 0.004 265);
  --foreground: oklch(0.99 0 0);
  --card: oklch(0.178 0 0);
  --card-foreground: oklch(0.99 0 0);
  --popover: oklch(0.19 0.004 265);
  --popover-foreground: oklch(0.99 0 0);
  --primary: oklch(0.86 0 0);
  --primary-foreground: oklch(0.16 0.006 260);
  --secondary: oklch(0.21 0.004 265);
  --secondary-foreground: oklch(0.99 0 0);
  --muted: oklch(0.2 0.004 265);
  --muted-foreground: oklch(0.68 0.008 270);
  --accent: oklch(0.24 0.006 268);
  --accent-foreground: oklch(0.99 0 0);
  --destructive: oklch(0.68 0.21 25);
  --destructive-foreground: oklch(0.99 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.64 0.15 265);
  --highlight: oklch(0.76 0.15 42);
  --highlight-foreground: oklch(0.2 0.05 40);
  --glow: oklch(0.6 0.18 268);
  --chart-1: oklch(0.68 0.21 5);
  --chart-2: oklch(0.74 0.19 148);
  --chart-3: oklch(0.71 0.15 250);
  --chart-4: oklch(0.87 0.13 95);
  --chart-5: oklch(0.68 0.2 305);
  --sidebar: oklch(0.155 0.004 265);
  --sidebar-foreground: oklch(0.99 0 0);
  --sidebar-primary: oklch(0.6 0.18 268);
  --sidebar-primary-foreground: oklch(0.99 0 0);
  --sidebar-accent: oklch(0.24 0.006 268);
  --sidebar-accent-foreground: oklch(0.99 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.64 0.15 265);
}
